begin;
select pg_advisory_xact_lock(hashtext('race-fixes-2026-11-01'));
do $$ begin
if exists(select 1 from event_facts where method='manual_race_fixes_20261101' and field='batch_complete') then raise exception 'Already applied'; end if;
