end $$;
create temporary table repair_before on commit drop as select id,to_jsonb(events) as data from events where id in ('258bb5a5-8cc3-4cfb-8726-4211db0fc7a5','a18b06a4-03b7-4b7c-a0f4-ece6a475441f','c04842aa-824c-4879-af74-3013d5c47681');
